def rotate_matrix(matrix: list[list[int]]) -> None:
    n = len(matrix)
    # Transpose the matrix
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
    # Reverse each row
    for i in range(n):
        matrix[i].reverse()
```

```python
def is_valid_sudoku(board: list[list[str]]) -> bool:
    # Validate rows
    for row in board:
        seen = set()
        for cell in row:
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Validate columns
    for col in range(9):
        seen = set()
        for row in range(9):
            cell = board[row][col]
            if cell != '.':
                if cell in seen:
                    return False
                seen.add(cell)

    # Validate 3x3 sub-boxes
    for box_row in range(0, 9, 3):
        for box_col in range(0, 9, 3):
            seen = set()
            for i in range(3):
                for j in range(3):
                    cell = board[box_row + i][box_col + j]
                    if cell != '.':
                        if cell in seen:
                            return False
                        seen.add(cell)

    return True
```

```python
def eval_rpn(tokens: list[str]) -> int:
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Integer division truncating toward zero
                if (a >= 0) == (b >= 0):
                    stack.append(abs(a) // abs(b))
                else:
                    stack.append(-(abs(a) // abs(b)))
        else:
            stack.append(int(token))
    return stack[0]
```

