def compress_string(s: str) -> str:
    if not s:
        return s

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1])
            compressed.append(str(count))
            count = 1

    compressed.append(s[-1])
    compressed.append(str(count))

    result = "".join(compressed)
    return result if len(result) < len(s) else s

