def count_and_say(n: int) -> str:
    if n <= 0:
        return ""
    s = "1"
    for _ in range(n - 1):
        next_s = []
        i = 0
        while i < len(s):
            j = i
            while j < len(s) and s[j] == s[i]:
                j += 1
            next_s.append(str(j - i))
            next_s.append(s[i])
            i = j
        s = "".join(next_s)
    return s

def transpose_matrix(matrix: list[list[int]]) -> list[list[int]]:
    if not matrix:
        return []
    return [list(row) for row in zip(*matrix)]

